/**
 * First boot: the secrets a gate needs, generated by the gate instead of by its operator.
 *
 * Runs before the config is read. For each secret below that the environment does not set, the
 * value is read from the state store, or generated and stored when there is none, then placed in
 * `process.env` so every existing reader keeps reading one place. A value set in the environment
 * always wins and is never copied into the store: an operator who manages secrets elsewhere keeps
 * doing so.
 *
 * Never generated: the MAINNET relayer key. It pays real gas, so it is funded and set on purpose.
 */
import { generateKeyPairSync, randomBytes } from "node:crypto";
import type { GateStateStore } from "@naulon/shared";

export interface GeneratedSecret {
  name: string;
  /** What the secret is for, said once in the boot log. */
  purpose: string;
  generate: () => string;
  /** Whether this gate needs it at all, judged from the environment. */
  needed: (env: NodeJS.ProcessEnv) => boolean;
}

/** secp256k1's group order: a private key must be below it and above zero. */
const SECP256K1_N = 0xfffffffffffffffffffffffffffffffebaaedce6af48a03bbfd25e8cd0364141n;

export function secp256k1PrivateKey(): string {
  for (;;) {
    const hex = randomBytes(32).toString("hex");
    const n = BigInt(`0x${hex}`);
    if (n > 0n && n < SECP256K1_N) return `0x${hex}`;
  }
}

const MEMO_TESTNETS = new Set(["arcTestnet"]);

export const GENERATED_SECRETS: readonly GeneratedSecret[] = [
  {
    name: "TOLLGATE_SECRET",
    purpose: "signs payment nonces, so every instance accepts the others'",
    generate: () => randomBytes(32).toString("hex"),
    needed: () => true,
  },
  {
    name: "LICENSE_SIGNING_KEY",
    purpose: "signs the licences buyers receive; its public half is served at /.well-known/naulon-jwks.json",
    generate: () => generateKeyPairSync("ed25519").privateKey.export({ type: "pkcs8", format: "pem" }).toString(),
    needed: () => true,
  },
  {
    name: "RELAYER_PRIVATE_KEY",
    purpose: "pays testnet gas to relay a buyer's transfer; it never holds the payment",
    generate: secp256k1PrivateKey,
    needed: (env) => MEMO_TESTNETS.has(env.SETTLEMENT_NETWORK?.trim() || "arcTestnet"),
  },
];

const storeKey = (name: string): string => `secret:${name.toLowerCase()}`;

export interface BootstrapReport {
  /** Secrets this boot created. Said in the log once, never with their value. */
  generated: string[];
  /** Secrets read back from the store, made on an earlier boot or by another instance. */
  restored: string[];
}

export async function bootstrapSecrets(
  store: GateStateStore,
  env: NodeJS.ProcessEnv = process.env,
  secrets: readonly GeneratedSecret[] = GENERATED_SECRETS,
): Promise<BootstrapReport> {
  const report: BootstrapReport = { generated: [], restored: [] };
  for (const s of secrets) {
    if (env[s.name]?.trim()) continue;
    if (!s.needed(env)) continue;
    const key = storeKey(s.name);
    const candidate = s.generate();
    const held = await store.createIfAbsent(key, candidate);
    env[s.name] = held;
    (held === candidate ? report.generated : report.restored).push(s.name);
  }
  return report;
}

export function describeBootstrap(report: BootstrapReport, where: string): string[] {
  return report.generated.map((name) => {
    const s = GENERATED_SECRETS.find((g) => g.name === name);
    return `[naulon] generated ${name} and stored it in ${where}: it ${s?.purpose ?? "is required"}. Set ${name} yourself to manage it elsewhere.`;
  });
}
